/* A task-focused interface over the existing sampling and evidence APIs. */
let researchStep=1,researchResultTab='overview',researchMessage='';
const researchVendors={'OpenAI':['OpenAI','O','#131b2c'],'Google':['Google','G','#4285f4'],'Anthropic':['Anthropic','A','#b97753'],'DeepSeek':['DeepSeek','D','#4d6bfe'],'阿里千问':['通义千问','Q','#111113'],'智谱':['智谱 GLM','Z','#3655da'],'月之暗面':['Kimi','K','#222227'],'腾讯混元':['腾讯混元','H','#1678d2'],'小米':['小米 MiMo','M','#f17825'],'MiniMax':['MiniMax','M','#e05b79']};
const researchWhen=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});
function researchGroups(){const g={};for(const p of geoState.runner.profiles.filter(p=>p.markets.includes(geoMarket)))(g[p.manufacturer||p.model]||=[]).push(p);return Object.entries(g)}
function researchChoices(){const selected=geoDraft[geoMarket].providers||[];return researchGroups().map(([vendor,ps])=>({vendor,ps,p:ps.find(p=>selected.includes(p.id))||ps.find(p=>p.channel==='direct')||ps[0],selected:ps.some(p=>selected.includes(p.id))}))}
function researchField(label,id,value='',placeholder='',multiline=false,optional=false){return `<label class="ru-field" for="${id}"><span>${label}${optional?'<small>选填</small>':''}</span>${multiline?`<textarea id="${id}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off">`}</label>`}
function researchSave(){const d=geoDraft[geoMarket];const value=id=>$('#'+id)?.value;for(const k of ['website','context','focus','generator','questions'])if(value('geo-'+k)!==undefined)d[k]=value('geo-'+k);if(value('ru-brand')!==undefined||value('ru-aliases')!==undefined){const name=(value('ru-brand')??(d.brand||'').split('|')[0]).trim();const extra=value('ru-aliases')??(d.brand||'').split('|').slice(1).join(', ');d.brand=[name,...extra.split(/[,，|]/).map(s=>s.trim()).filter(Boolean)].filter(Boolean).join(' | ')}for(const [key,id] of [['skus','ru-products'],['competitors','ru-competitors']])if(value(id)!==undefined){const old=geoRows(d[key],key==='competitors');d[key]=value(id).split('\n').map(s=>s.trim()).filter(Boolean).map(name=>{const r=old.find(r=>r.name===name);return r?[r.name,...r.aliases.filter(a=>a!==r.name)].join(' | ')+(r.domains?.length?' ; '+r.domains.join(','):''):name}).join('\n')}if(value('ru-sku-aliases')!==undefined)d.skus=value('ru-sku-aliases');if(value('ru-competitor-aliases')!==undefined)d.competitors=value('ru-competitor-aliases');d.count='30';d.repeats='1';if(!(typeof geoBrowser==='function'&&geoBrowser())&&!(typeof geoRemoteMode==='function'&&geoRemoteMode()))localStorage.setItem('signal-research-drafts',JSON.stringify(geoDraft))}
geoCapture=researchSave;
function researchNext(step){researchSave();researchMessage='';if(step===2){const d=geoDraft[geoMarket];if(!d.brand?.split('|')[0].trim()||!d.website?.trim()){researchMessage='请先填写品牌名称和官网地址。';render();return}try{d.website=d.website.trim();if(!/^https?:\/\//i.test(d.website))d.website='https://'+d.website;const u=new URL(d.website);if(!['https:','http:'].includes(u.protocol)||!u.hostname.includes('.'))throw Error()}catch{researchMessage='请输入正确的官网域名，例如 example.com。';render();return}}researchStep=step;render();window.scrollTo({top:0,behavior:'smooth'})}
geoChange=function(m){researchSave();geoMarket=m;localStorage.setItem('signal-research-market',m);geoActive=null;clearTimeout(geoTimer);researchStep=1;researchMessage='';render()};
function researchToggle(vendor){researchSave();const g=researchChoices().find(g=>g.vendor===vendor),d=geoDraft[geoMarket],ids=new Set(g.ps.map(p=>p.id));d.providers=(d.providers||[]).filter(id=>!ids.has(id));if(!g.selected)d.providers.push(g.p.id);render()}
function researchModel(vendor,pid){const g=researchChoices().find(g=>g.vendor===vendor),d=geoDraft[geoMarket];d.providers=(d.providers||[]).filter(id=>!g.ps.some(p=>p.id===id));d.providers.push(pid);render()}
function researchSteps(){return `<div class="ru-steps">${['填写品牌','选择 AI','查看结果'].map((x,i)=>`<button class="${researchStep===i+1?'current':researchStep>i+1?'complete':''}" onclick="researchNext(${i+1})"><span>${researchStep>i+1?'✓':i+1}</span>${x}</button>`).join('')}</div>`}
function researchBrand(){const d=geoDraft[geoMarket];return `<div class="ru-section-head"><span class="ru-kicker">01 / 品牌信息</span><h2>你想分析哪个品牌？</h2><p>告诉我们品牌和官网，系统会生成适合这个市场的 30 道问题。</p></div><div class="ru-two">${researchField('品牌名称','ru-brand',(d.brand||'').split('|')[0].trim(),'例如：欧莱雅')}${researchField('品牌官网','geo-website',d.website||'','https://www.example.com')}</div>${typeof brandAutofillMarkup==='function'?brandAutofillMarkup():''}<div class="ru-two">${researchField('重点产品','ru-products',geoRows(d.skus).map(r=>r.name).join('\n'),'每行一个，例如：玻尿酸精华\n维 C 精华',true,true)}${researchField('主要竞品','ru-competitors',geoRows(d.competitors,true).map(r=>r.name).join('\n'),'每行一个，例如：玉兰油\n妮维雅',true,true)}</div><details class="ru-optional"><summary>补充产品和用户背景 <span>让问题更贴近你的业务</span></summary>${researchField('产品类别、目标人群或主要功效','geo-context',d.context||'','例如：面向 25–40 岁用户的日常抗老护肤产品',true,true)}${researchField('想重点了解的需求','geo-focus',d.focus||'','例如：保湿、淡纹、性价比',false,true)}</details><p class="ru-help">中国和美国可以使用不同官网、产品与竞品，分析结果分别保存。</p><div class="ru-footer"><span>下一步：选择要比较的 AI</span><button class="primary ru-main" onclick="researchNext(2)">下一步：选择 AI <span>→</span></button></div>`}
function researchSelect(){const groups=researchChoices(),selected=groups.filter(g=>g.selected);return `<div class="ru-section-head"><span class="ru-kicker">02 / 分析范围</span><h2>想了解哪些 AI 会提及你的品牌？</h2><p>点选要测试的厂商。每家使用一个模型，回答同一组 30 道问题。</p></div><div class="ru-model-grid">${groups.map(g=>{const [name,letter,color]=researchVendors[g.vendor]||[g.vendor,g.vendor[0],'#111113'];return `<button class="ru-model ${g.selected?'selected':''}" aria-pressed="${g.selected}" onclick="researchToggle('${esc(g.vendor)}')"><span class="ru-model-logo" style="--brand-color:${color}">${letter}</span><span><b>${esc(name)}</b><small>${esc(g.p.model||g.p.name)}</small></span><span class="ru-check">${g.selected?'✓':'+'}</span></button>`}).join('')||(typeof geoBrowser==='function'&&geoBrowser()?'<div class="ru-empty"><b>尚无可用的固定模型目录</b><p>在本页连接 B.AI；若已连接，请检查账号是否有受支持的固定文本模型。</p><button class="primary" onclick="browserResearchConnect()">连接 / 更换 AI</button></div>':'<div class="ru-empty"><b>还没有可用的 AI 连接</b><a class="button primary" href="http://127.0.0.1:8771/#/w/demo/bai" target="_blank" rel="noopener">去连接 AI ↗</a><button onclick="geoRefresh()">连接后刷新</button></div>')}</div><div class="ru-plan"><div><b>30 道不同问题</b><span>每题问一次 · 每家一个模型</span></div><strong>${selected.length*30}<small>次回答</small></strong></div><p class="ru-help">还会调用出题模型 3 次。模型服务按实际用量计费；不会自动充值。</p><details class="ru-optional"><summary>高级设置 <span>更换模型、品牌别名和自定义题目</span></summary>${researchAdvanced()}<div class="actions"><button onclick="geoPreview()">核对调用计划</button><button onclick="geoGenerateOnly()">只生成问题，暂不测试</button></div><div id="geo-plan"></div><p id="geo-error" class="error" role="alert"></p></details><div class="ru-footer"><button class="ghost" onclick="researchNext(1)">← 返回品牌信息</button><button class="primary ru-main" ${!geoToken||!selected.length||geoState.busy?'disabled':''} onclick="geoStart(false)">开始分析 <span>→</span></button></div>${!geoLocal()?'<p class="ru-warning">请先在本页连接 AI，再明确开始分析。</p>':''}`}
function researchAdvanced(){const d=geoDraft[geoMarket];return `<div class="ru-two">${researchField('品牌其他名称（逗号分隔）','ru-aliases',(d.brand||'').split('|').slice(1).map(s=>s.trim()).join(', '),'例如：巴黎欧莱雅, L’Oréal Paris') }<label class="ru-field"><span>用于生成问题的模型</span><select id="geo-generator">${geoOptions()}</select></label></div>${researchChoices().filter(g=>g.selected&&g.ps.length>1).map(g=>`<label class="ru-field"><span>${esc(g.vendor)}：本次使用哪个模型？</span><select onchange="researchSave();researchModel('${esc(g.vendor)}',this.value)">${g.ps.map(p=>`<option value="${esc(p.id)}" ${p.id===g.p.id?'selected':''}>${esc(p.name)} · ${esc(p.model)}${p.channel==='direct'?' · 官方直连':' · 聚合服务'}</option>`).join('')}</select></label>`).join('')}<details class="ru-optional"><summary>产品与竞品的精确匹配设置</summary><p class="ru-help">仅在名称有不同写法时调整。每行用 | 分隔名称和别名；竞品域名放在分号后。</p>${researchField('产品名称与别名','ru-sku-aliases',d.skus||'','',true)}${researchField('竞品名称、别名与域名','ru-competitor-aliases',d.competitors||'','',true)}</details>${researchField('自定义题目（每行一道）','geo-questions',d.questions||'','有自己的题库时填写；留空则自动生成',true,true)}<button onclick="geoStart(true)">使用这些题目分析</button>${typeof geoBrowser==='function'&&geoBrowser()?'<p class="ru-help">模型只来自账号实际目录，Chat Completions 兼容性需实际调用验证。浏览器不请求联网工具；完整模型 ID 与真实响应保留在证据中。</p>':`<p><a href="http://127.0.0.1:8771/#/w/demo/bai" target="_blank" rel="noopener">管理聚合服务连接 ↗</a>　<a href="http://127.0.0.1:8770/#/w/demo/apis?api_market=${geoMarket}" target="_blank" rel="noopener">管理官方 API 连接 ↗</a></p>`}`}
geoStart=async function(manual,generateOnly=false){try{researchMessage='';const body=geoPayload();if(manual)body.count=body.prompts.length;body.generate_only=generateOnly;if(!body.providers.length)throw Error('请至少选择一家 AI 厂商。');if(!body.generator)body.generator=body.providers[0];const job=await geoFetch(manual?'sample':'start',body);geoActive=job;geoDraft[geoMarket].last=job.id;researchStep=3;researchResultTab='overview';await geoRefresh(false);await geoOpen(job.id)}catch(e){researchMessage=e.message;render()}};
async function researchOpen(id){researchStep=3;researchResultTab='overview';await geoOpen(id);const c=geoActive?.config;if(c){const d=geoDraft[geoMarket];d.website=c.website;d.brand=c.brand_aliases.join(' | ');d.skus=(c.skus||[]).map(k=>[k.name,...k.aliases.filter(a=>a!==k.name)].join(' | ')).join('\n');d.competitors=(c.competitors||[]).map(k=>[k.name,...k.aliases.filter(a=>a!==k.name)].join(' | ')+(k.domains?.length?' ; '+k.domains.join(','):'')).join('\n');d.context=c.context||'';d.focus=c.focus||'';render()}}
function researchDisplayModel(pid){return geoModel(pid)}
function researchMetrics(r){const ms=r.groups?.discovery?.models||r.models||[];let hits=0,total=0,positions=0,ranked=0,citations=0;for(const m of ms){const b=m.brands.find(b=>b.own);if(!b)continue;hits+=b.mentions;total+=b.denominator;citations+=b.citation_answers;if(b.average_rank!==null&&b.ranked_samples){positions+=b.average_rank*b.ranked_samples;ranked+=b.ranked_samples}}return{ms,hits,total,citations,score:total?Math.round(100*hits/total):null,rank:ranked?(positions/ranked).toFixed(1):null}}
function researchResults(){const j=geoActive;if(!j)return `<div class="ru-empty"><span class="ru-empty-icon">↗</span><h2>你的第一份品牌分析，从这里开始</h2><p>选择品牌和 AI 后，我们会把结果整理在这里。</p><button class="primary" onclick="researchNext(1)">开始一次新分析</button></div>`;const r=j.report,running=['running','queued'].includes(j.status),completed=j.samples.filter(s=>s.status==='complete').length,planned=j.plan?.answer_calls||j.config.providers.length*j.prompts.length,progress=planned?Math.min(100,Math.round(100*j.samples.length/planned)):0;return `<div class="ru-result-heading"><div><span class="ru-kicker">${geoMarket==='CN'?'中国市场':'美国市场'} · ${esc(researchWhen(j.created_at))}</span><h2>${esc(j.config.brand_aliases[0])}${r?'的 AI 表现':'的分析进度'}</h2><p>${running?'分析正在进行，已完成的回答会陆续显示。':(!r&&j.prompts.length?`${j.prompts.length} 道问题已生成 · 等待测试 AI`:`${j.prompts.length} 道题 · ${j.config.providers.length} 家 AI · ${completed} 条完整回答`)}</p></div><div class="actions"><select aria-label="选择历史报告" onchange="researchOpen(this.value)">${geoState.runs.filter(x=>x.market===geoMarket).map(x=>`<option value="${x.id}" ${x.id===j.id?'selected':''}>${esc(researchWhen(x.created_at))} · ${esc(x.brand)} · ${geoStatus[x.status]||esc(x.status)}</option>`).join('')}</select><button onclick="geoExport()">↓ 下载分析证据</button></div></div>${running?`<div class="ru-running"><b>${geoStage[j.stage]||'正在分析'}</b><span>${j.stage==='generating'?`题目生成 ${j.generation_progress?.complete||0} / ${j.plan?.generation_batches||3} 批`:`回答进度 ${j.samples.length} / ${planned}`}</span><div class="bar"><i style="width:${progress}%;background:#111113"></i></div><button class="small" onclick="geoStop()">停止后续分析</button></div>`:''}${j.error||j.status==='partial'?`<div class="ru-warning"><b>${j.error?'这次分析没有全部完成':'部分 AI 未能完成回答'}</b><p>${j.error?esc(researchFriendlyError(j.error)):'成功回答已保留；失败回答不会被算成零分。可在回答明细查看原因。'}</p>${j.prompt_hash&&!(typeof geoBrowser==='function'&&geoBrowser())?'<button onclick="geoResume()">继续未完成的部分</button>':'<button onclick="researchNext(2)">检查 AI 选择</button>'}</div>`:''}${!r?(j.prompts.length&&!running&&!j.error?'<div class="ru-empty"><span class="ru-empty-icon">✓</span><h2>'+j.prompts.length+' 道问题已准备好</h2><p>接下来让所选 AI 回答这些问题，就能看到品牌和产品的表现。</p><button class="primary ru-main" style="margin:22px auto" onclick="geoStart(true)">开始测试所选 AI →</button><p class="ru-help">这一步会调用模型，按服务商实际用量计费。</p></div>':'<div class="ru-empty"><p>还没有可分析的回答，暂时不显示分数。</p></div>'):researchReport(r,j)}<details class="ru-optional"><summary>查看题目与计算依据 <span>原始回答、匹配设置和计算口径</span></summary><p class="ru-help">分数表示本次未点名品牌的问题中，完整回答提及品牌的比例；明确列表位置按原文统计。API 模型结果不等同于各家 App 的全部表现。</p><div class="actions"><button onclick="downloadJSON(geoActive.prompts,'brand-questions.json')">下载本次题目</button><button onclick="geoReanalyze()">按当前品牌设置重新分析（不调用模型）</button></div>${researchAdvanced()}</details>`}
function researchFriendlyError(text){if(/HTTP (400|401|403|404|429)/.test(text))return '模型服务拒绝了请求，请检查账户余额、使用权限或模型连接。已完成的内容已保存。';return text}
function researchReport(r,j){const m=researchMetrics(r);return `<div class="ru-kpis"><div><span>品牌提及率</span><strong>${m.score===null?'—':m.score+'<small>%</small>'}</strong><p>${m.hits} / ${m.total} 条有效回答提及你</p></div><div><span>平均列表位置</span><strong>${m.rank===null?'—':'<small>第</small> '+m.rank+' <small>位</small>'}</strong><p>只统计回答中明确给出的序号</p></div><div><span>竞品领先的问题</span><strong>${m.total?r.gaps.length:'—'}<small>条</small></strong><p>竞品出现，你的品牌没有出现</p></div><div><span>引用品牌官网</span><strong>${m.total?m.citations:'—'}<small>次</small></strong><p>只计 AI 返回的引用信息</p></div></div>${m.total>0&&m.total<10?'<p class="ru-help">当前有效回答较少，这份结果适合试测，暂不足以判断整体表现。</p>':''}<div class="ru-result-tabs">${[['overview','各家 AI 表现'],['products','产品表现'],['gaps','竞品机会'],['sources','引用来源'],['answers','回答明细']].map(([k,v])=>`<button class="${researchResultTab===k?'active':''}" onclick="researchResultTab='${k}';render()">${v}</button>`).join('')}</div>${researchResultBody(r,j,m)}`}
function researchResultBody(r,j,m){if(researchResultTab==='overview')return `<div class="ru-comparison">${m.ms.map(v=>{const b=v.brands.find(b=>b.own);return `<div class="ru-comparison-row"><div><b>${esc(researchDisplayModel(v.provider))}</b><small>${v.eligible?'已获得 '+v.eligible+' 条有效回答':'暂未获得有效回答'}</small></div><div class="bar"><i style="width:${b?.score||0}%;background:#111113"></i></div><strong>${b?.score===null||b?.score===undefined?'—':b.score+'%'}</strong></div>`}).join('')}</div><div class="ru-insight"><b>下一步可以看什么？</b><p>${r.gaps.length?'先看“竞品机会”，找到竞品出现而你没出现的具体问题。':'查看“产品表现”，了解哪些产品被提到；再从“回答明细”核对具体语境。'}</p></div><details class="ru-optional"><summary>查看品牌认知与比较题的结果</summary>${geoReport(r,j)}</details>`;if(researchResultTab==='products')return m.ms.map(v=>`<h3 class="ru-model-title">${esc(researchDisplayModel(v.provider))}</h3>${v.skus.length?table(['产品','提及率','被提及的回答','平均列表位置'],v.skus.map(k=>`<tr><td>${esc(k.name)}</td><td>${k.score===null?'—':k.score+'%'}</td><td>${k.mentions} / ${k.denominator}</td><td>${k.average_rank===null?'未明确给出':k.average_rank}</td></tr>`).join('')):'<p class="ru-help">这次没有设置重点产品。可返回品牌信息补充，再用现有回答重新分析。</p>'}`).join('');const old=geoTab;geoTab=researchResultTab==='gaps'?'gaps':researchResultTab==='sources'?'sources':'answers';const html=geoReport(r,j);geoTab=old;return html}
function researchHistory(){const runs=geoState.runs.filter(r=>r.market===geoMarket).slice(0,5);return runs.length?`<section class="ru-history"><h3>最近的分析</h3>${runs.map(r=>`<button onclick="researchOpen('${r.id}')"><span><b>${esc(r.brand)}</b><small>${esc(researchWhen(r.created_at))}</small></span><span class="tag ${r.status==='failed'?'warn':''}">${geoStatus[r.status]||esc(r.status)} →</span></button>`).join('')}</section>`:''}
function researchSummary(){const d=geoDraft[geoMarket],selected=researchChoices().filter(g=>g.selected);return `<aside class="ru-summary"><div class="ru-summary-icon">∿</div><span class="ru-kicker">这次你会得到</span><h3>看清本批 AI 回答是否提及你的品牌</h3><ul><li>品牌与产品的提及表现</li><li>回答中的推荐列表位置</li><li>竞品覆盖、你遗漏的问题</li><li>AI 引用的页面和原始回答</li></ul><div class="ru-summary-line"><span>分析市场</span><b>${geoMarket==='CN'?'中国':'美国'}</b></div><div class="ru-summary-line"><span>问题数量</span><b>30 道，每题一次</b></div><div class="ru-summary-line"><span>已选 AI</span><b>${selected.length} 家</b></div><p>各家 AI 回答同一组问题，结果可以直接对照。</p>${typeof geoBrowser==='function'&&geoBrowser()?'<button class="primary" onclick="browserResearchConnect()">连接 / 管理 AI</button>':!geoLocal()?'<a class="button primary" href="http://127.0.0.1:8772/#/w/demo/research">打开本机分析工作台 ↗</a>':''}${researchHistory()}</aside>`}
geoPage=function(){return `<div class="ru-topline"><div><span class="ru-kicker">SIGNAL GEO / 品牌分析</span><h1>你的品牌，AI 看得见吗？</h1><p>从官网出发，用真实回答了解品牌表现。</p></div><div class="ru-markets" aria-label="分析市场"><button class="${geoMarket==='CN'?'active':''}" onclick="geoChange('CN')">中国</button><button class="${geoMarket==='US'?'active':''}" onclick="geoChange('US')">美国</button></div></div>${researchSteps()}${researchMessage?`<p class="ru-warning" role="alert">${esc(researchFriendlyError(researchMessage))}</p>`:''}<div class="ru-layout ${researchStep===3?'ru-layout-results':''}"><section class="ru-main-card">${researchStep===1?researchBrand():researchStep===2?researchSelect():researchResults()}</section>${researchStep===3?'':researchSummary()}</div>`};
const researchBaseRender=render;render=function(){researchBaseRender();document.body.classList.toggle('research-mode',page==='research');if(page!=='research')return;const navEl=document.querySelector('aside nav');if(navEl)navEl.innerHTML=`<a href="#/w/${ws}/research" class="${researchStep<3?'active':''}" onclick="researchNext(1);return false">＋ 开始品牌分析</a><a href="#/w/${ws}/research" class="${researchStep===3?'active':''}" onclick="researchNext(3);return false">▤ 分析报告</a><div class="label">管理</div>${typeof geoBrowser==='function'&&geoBrowser()?'<a href="#" onclick="browserResearchConnect();return false">⚙ AI 连接设置</a>':'<a href="http://127.0.0.1:8771/#/w/demo/bai" target="_blank" rel="noopener">⚙ AI 连接设置 ↗</a>'}<a href="#/w/${ws}/overview">全部工作台功能 →</a>`;document.querySelector('header .actions > span').textContent='品牌 AI 可见度分析';document.querySelector('.header-right .tag').textContent=typeof geoBrowser==='function'&&geoBrowser()?(geoToken?'浏览器直连':'待连接 AI'):geoLocal()?'本机工作台':'在线入口'};
if(page==='research'){render();window.scrollTo(0,0);}
